import React from "react";

interface CounterProps {
  value: number;
  onIncrement: () => void;
  onDecrement: () => void;
}

export function Counter({ value, onIncrement, onDecrement }: CounterProps) {
  return (
    <div className="inline-flex items-center gap-3 bg-bg border border-border rounded-full px-2 py-1">
      <button
        type="button"
        onClick={onDecrement}
        className="w-6 h-6 rounded-full bg-field text-text flex items-center justify-center hover:bg-raised cursor-pointer text-sm font-semibold"
      >
        –
      </button>
      <span className="font-inter text-[15px] font-semibold text-text min-w-[20px] text-center">
        {value}
      </span>
      <button
        type="button"
        onClick={onIncrement}
        className="w-6 h-6 rounded-full bg-green-primary text-text flex items-center justify-center hover:brightness-110 cursor-pointer text-sm font-semibold"
      >
        +
      </button>
    </div>
  );
}
